#include <bits/stdc++.h>
#define LL long long
#define U unsigned
#define INF 0x7fffffffffffffff
#define MINF -0x8000000000000000
bool is_prime(LL x){
    if(x<2) return false;
    for(LL i=2; i<=sqrt(x); i++){
        if(x%i==0) return false;
    }
    return true;
}
inline LL read_input()
{
    LL x=0,f=1; char ch=getchar();
    while (!isdigit(ch)){ if (ch=='-') f=-1; ch=getchar(); }
    while (isdigit(ch)){ x=x*10+ch-48; ch=getchar(); }
    return x*f;
}
LL gcd_value(LL x, LL y){
    return y==0 ? x : gcd_value(y, x%y);
}
LL fast_pow(LL base, LL exp, LL mod){
    LL result=1;
    for(; exp; exp>>=1){
        if(exp%2) result=result*base%mod;
        base=base*base%mod;
    }
    return result;
}
using namespace std;
/* Additional code omitted for brevity, same as original */
#define MOD1 998244353LL
#define MOD2 1000000007LL
LL totalN;
LL totalCount;
LL firstSum[7];
vector<LL> firstDigits[7];

void generate_numbers(LL depth, LL current){
    if(depth>6) return;
    firstDigits[depth].push_back((totalCount - current + MOD1)%MOD1);
    firstSum[depth]+=(totalCount - current + MOD1)%MOD1;
    totalCount++;
    for(LL digit=0; digit<=9; digit++){
        generate_numbers(depth+1, current*10+digit);
    }
}

LL counter2=-1, answer;
void process_numbers(LL depth, LL current){
    if(current>N) return;
    if(current*1000000+999999<=N && current*10000000>N){
        for(LL i=0; i<=6; i++){
            LL shift=(counter2+1 - current*fast_pow(10,i,MOD1)%MOD1 + MOD1)%MOD1;
            LL pos=lower_bound(firstDigits[i].begin(), firstDigits[i].end(), MOD1-shift) - firstDigits[i].begin();
            answer += (firstSum[i] + shift*firstDigits[i].size() - MOD1*(firstDigits[i].size()-pos));
            answer %= MOD2;
        }
        counter2+=totalCount;
        return;
    }
    counter2++;
    answer += ((counter2 - current)%MOD1 + MOD1)%MOD1;
    answer %= MOD2;
    for(LL digit=0; digit<=9; digit++){
        if(!depth && digit==0) continue;
        process_numbers(depth+1, current*10+digit);
    }
}

int main(){
    totalN=read_input();
    generate_numbers(0,0);
    for(LL i=0; i<=6; i++) sort(firstDigits[i].begin(), firstDigits[i].end());
    process_numbers(0,0);
    std::cout<<answer;
    return 0;
}
